/**
 * The Outcry
 * ----------
 * The people cry out against the Jewish nobles who charge interest, and Nehemiah charges them to give back the fields and the interest. Stage: a courtyard at midday, a crowd of the poor, a governor listening, a money lender's ledger; the debt being cancelled, a people set free.
 *
 * Palette 0x1a2a14 → 0x060402 · light: ember · hero: pillar
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./nehemiah-kit.js.
 */

import { THREE, createScene, pillar, person, crowd } from './nehemiah-kit.js';

const BG = 0x1a2a14;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 3119112422, bg: BG, fogNear: 45, fogFar: 180 });

    /* light — ember */
    W.lights({ sky: 0x3a2418, gnd: 0x1a0e08, hemi: 0.4, sun: 0xff7a30, sunI: 0.7, sunPos: [20, 26, 30] });

    W.stars(90, 150, [0xf0e0c8, 0xd8c0a0], 0.7);
    W.disc([0, 34, -150], 14, 0xff8a30, 0.12);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* hero: the standing stone */
    pillar(W, group, 0, 0, 0, 1.15, { stone: 0x060402 });
    W.disc([0, 6, -12], 5, 0x22371a, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x8a6a44, head: 'wrap', wrap: 0x1e3017, wrapTrim: 0x121d0e, beard: 'long', ry: 0.61, s: 1.07 });
    person(W, group, [4.5, 0, 6], { robe: 0x8a6a44, head: 'wrap', wrap: 0x1e3017, wrapTrim: 0x121d0e, beard: 'long', ry: -0.43, s: 1.08 });
    person(W, group, [1, 0, -5], { robe: 0x8a6a44, head: 'wrap', wrap: 0x1e3017, wrapTrim: 0x121d0e, beard: 'long', ry: -0.12, s: 1.02 });
    /* crowd: the people of the story */
    crowd(W, group, 0, 16, 15, 70, 44, [0x1a2a14, 0x060402, 0x8a6a44, 0x6a4a30, 0xc8b088, 0x5a4a6a]);

    return W.finish();
}

export default { build };
